import React, { Component } from 'react';
import ButtonGroup from '@mui/material/ButtonGroup';
import { withStyles } from '@mui/styles'; // Ensure @mui/styles is installed
import Button from '@mui/material/Button';
import SvgIcon from '@mui/material/SvgIcon';
import mirador from 'mirador';

const { selectors } = mirador;
const { getViewer } = selectors;

// Custom icons - Refactored for React 19 (camelCase attributes)
const ZoomInIcon = (props) => (
  <SvgIcon {...props}>
    <svg xmlns='http://www.w3.org/2000/svg' width='24' height='24' viewBox='0 0 24 24'>
      <circle cx='10.5' cy='10.5' r='5.5' fill='none' stroke='currentColor' strokeLinejoin='bevel' strokeWidth='1.4'/>
      <line x1='14.5' y1='14.5' x2='19' y2='19' fill='none' stroke='currentColor' strokeLinecap='square' strokeLinejoin='bevel' strokeWidth='1.4'/>
      <rect x='10' y='8' width='1' height='5' fill='currentColor'/>
      <rect x='10' y='8' width='1' height='5' transform='translate(21) rotate(90)' fill='currentColor'/>
    </svg>
  </SvgIcon>
);

const ZoomOutIcon = (props) => (
  <SvgIcon {...props}>
    <svg xmlns='http://www.w3.org/2000/svg' width='24' height='24' viewBox='0 0 24 24'>
        <circle cx='10.5' cy='10.5' r='5.5' fill='none' stroke='currentColor' strokeLinejoin='bevel' strokeWidth='1.4'/>
        <line x1='14.5' y1='14.5' x2='19' y2='19' fill='none' stroke='currentColor' strokeLinecap='square' strokeLinejoin='bevel' strokeWidth='1.4'/>
      <rect x='10' y='8' width='1' height='5' transform='translate(21) rotate(90)' fill='currentColor'/>
  </svg>
  </SvgIcon>
);

const styles = theme => ({
  CustomZoomButton: {
    backgroundColor: 'rgba(0,0,0,.8) !important',
    border: 0,
    borderRadius: 0,
    color: '#ffffff !important',
    height: 48,
    width: 48,
    marginLeft: '1px',
    '&:hover': {
      backgroundColor: 'rgba(0,0,0,1) !important',
    },
    '&:disabled': {
      color: 'rgba(255,255,255,.2) !important',
      backgroundColor: 'rgba(0,0,0,.5) !important',
    },
    '&:not(:last-child)': {
      border: 0,
    }
  }
})

class ZoomButtonsPlugin extends Component {
  constructor(props) {
    super(props);

    this.state = {
      viewerFullyLoaded: false,
    }

    this.handleZoomInClick = this.handleZoomInClick.bind(this);
    this.handleZoomOutClick = this.handleZoomOutClick.bind(this);
    this.imageLoaded = this.imageLoaded.bind(this);
    this.imageChange = this.imageChange.bind(this);
  }

  componentDidUpdate(prevProps) {
    const { viewer } = this.props;
    const { viewerFullyLoaded } = this.state;
    if (viewer && !viewerFullyLoaded) {
      viewer.addOnceHandler('tile-loaded', this.imageLoaded);
      viewer.addOnceHandler('close', this.imageChange);
    }
  }

  imageLoaded() {
    const { viewer } = this.props;
    this.setState({ viewerFullyLoaded: true });
    if (viewer) {
      viewer.removeHandler('tile-loaded', this.imageLoaded);
    }
  }

  imageChange() {
    const { viewer } = this.props;
    this.setState({ viewerFullyLoaded: false });
    if (viewer) {
      viewer.removeHandler('close', this.imageChange);
    }
  }

  handleZoomInClick() {
    const { windowId, updateViewport, viewer, windowViewProperties } = this.props;
    if (windowViewProperties && viewer && windowViewProperties.zoom <= viewer.viewport.getMaxZoom()) {
      updateViewport(windowId, {
        zoom: windowViewProperties.zoom * 2,
      });
    }
  }

  handleZoomOutClick() {
    const { windowId, updateViewport, viewer, windowViewProperties } = this.props;
    if (windowViewProperties && viewer && windowViewProperties.zoom >= viewer.viewport.getMinZoom()) {
      updateViewport(windowId, {
        zoom: windowViewProperties.zoom / 2,
      });
    }
  }

  render() {
    const { classes, viewer, windowViewProperties } = this.props;
    const { viewerFullyLoaded } = this.state;

    // Safety check for OSD viewport methods
    const zoomIn = ( windowViewProperties && viewer && viewer.viewport && windowViewProperties.zoom < viewer.viewport.getMaxZoom() );
    const zoomOut = ( windowViewProperties && viewer && viewer.viewport && windowViewProperties.zoom > viewer.viewport.getMinZoom() );

    return (
      <div className={!viewerFullyLoaded ? 'loader' : ''}>
        <div className='miradorZoomButtons'>
          <ButtonGroup size='large' disableElevation variant='contained' color='primary' >
            <Button className={classes.CustomZoomButton} aria-label='zoom in' onClick={this.handleZoomInClick} disabled={!zoomIn}>
              <ZoomInIcon />
            </Button>
            <Button className={classes.CustomZoomButton} aria-label='zoom out' onClick={this.handleZoomOutClick} disabled={!zoomOut}>
              <ZoomOutIcon />
            </Button>
          </ButtonGroup>
        </div>
      </div>
    );
  }
}

const mapStateToProps = (state, { windowId }) => (
  {
    windowViewProperties: getViewer(state, { windowId }),
  }
);

export default {
  component: withStyles(styles)(ZoomButtonsPlugin),
  mapStateToProps: mapStateToProps,
  target: 'OpenSeadragonViewer',
  mode: 'add',
};
